//! Generates `ui/src/generated/render_buffer.ts` from the render-buffer
//! layout defined once in `core/ir` (ARCHITECTURE.md §8.4), so Rust and
//! TypeScript cannot drift apart.
//!
//! `cargo run -p gen-ts` rewrites the file. The test in this crate fails
//! when the committed file differs from what would be generated, so
//! `cargo test --workspace` (and CI) catches a forgotten regeneration.

#![forbid(unsafe_code)]

use std::fmt::Write;

use ir::render::layout as l;
use ir::{DiagCode, SegFlags, SegKind, Severity};

/// Path of the generated file, relative to the repository root.
pub const OUTPUT: &str = "ui/src/generated/render_buffer.ts";

/// The generated TypeScript source.
pub fn generate() -> String {
    let mut s = String::new();
    // Writing to a String cannot fail.
    let _ = write_all(&mut s);
    s
}

fn object(s: &mut String, name: &str, doc: &str, fields: &[(&str, String)]) -> std::fmt::Result {
    writeln!(s, "/** {doc} */")?;
    writeln!(s, "export const {name} = {{")?;
    for (key, value) in fields {
        writeln!(s, "  {key}: {value},")?;
    }
    writeln!(s, "}} as const;\n")
}

fn write_all(s: &mut String) -> std::fmt::Result {
    writeln!(
        s,
        "// GENERATED by `cargo run -p gen-ts` from core/ir. Do not edit by hand.\n\
         // Render buffer layout version {} (ARCHITECTURE.md section 8.3).\n",
        l::VERSION
    )?;
    writeln!(s, "/** Header `magic` value. */")?;
    writeln!(s, "export const MAGIC = 0x{:08x};\n", l::MAGIC)?;
    writeln!(s, "/** Layout version these constants describe. */")?;
    writeln!(s, "export const VERSION = {};\n", l::VERSION)?;
    writeln!(s, "/** Header flag: more chunks follow (reserved). */")?;
    writeln!(s, "export const FLAG_PARTIAL = {};\n", l::FLAG_PARTIAL)?;
    writeln!(s, "/** Section alignment in bytes. */")?;
    writeln!(s, "export const ALIGN = {};\n", l::ALIGN)?;
    writeln!(s, "/** Bytes per vertex position (f32 x 3). */")?;
    writeln!(
        s,
        "export const VERTEX_POSITION_SIZE = {};\n",
        l::VERTEX_POSITION_SIZE
    )?;
    let n = |v: usize| v.to_string();
    object(
        s,
        "HEADER",
        "Header size and field byte offsets.",
        &[
            ("SIZE", n(l::HEADER_SIZE)),
            ("MAGIC", n(l::HEADER_MAGIC)),
            ("VERSION", n(l::HEADER_VERSION)),
            ("FLAGS", n(l::HEADER_FLAGS)),
            ("VERTEX_COUNT", n(l::HEADER_VERTEX_COUNT)),
            ("SEGMENT_COUNT", n(l::HEADER_SEGMENT_COUNT)),
            ("DIAG_COUNT", n(l::HEADER_DIAG_COUNT)),
            ("CHANNEL_COUNT", n(l::HEADER_CHANNEL_COUNT)),
            ("ORIGIN", n(l::HEADER_ORIGIN)),
            ("VERTICES_OFFSET", n(l::HEADER_VERTICES_OFFSET)),
            ("SEGMENTS_OFFSET", n(l::HEADER_SEGMENTS_OFFSET)),
            ("DIAGS_OFFSET", n(l::HEADER_DIAGS_OFFSET)),
            ("STRINGS_OFFSET", n(l::HEADER_STRINGS_OFFSET)),
        ],
    )?;
    object(
        s,
        "SEGMENT",
        "Segment table entry size and field byte offsets.",
        &[
            ("SIZE", n(l::SEGMENT_SIZE)),
            ("FIRST_VERTEX", n(l::SEGMENT_FIRST_VERTEX)),
            ("VERTEX_COUNT", n(l::SEGMENT_VERTEX_COUNT)),
            ("SRC_LINE", n(l::SEGMENT_SRC_LINE)),
            ("SRC_FILE_AND_BLOCK", n(l::SEGMENT_SRC_FILE_AND_BLOCK)),
            ("TOOL", n(l::SEGMENT_TOOL)),
            ("KIND", n(l::SEGMENT_KIND)),
            ("FLAGS", n(l::SEGMENT_FLAGS)),
            ("FEED", n(l::SEGMENT_FEED)),
            ("TIME", n(l::SEGMENT_TIME)),
        ],
    )?;
    object(
        s,
        "DIAG",
        "Diagnostic table entry size and field byte offsets.",
        &[
            ("SIZE", n(l::DIAG_SIZE)),
            ("SRC_LINE", n(l::DIAG_SRC_LINE)),
            ("SRC_FILE", n(l::DIAG_SRC_FILE)),
            ("SEVERITY", n(l::DIAG_SEVERITY)),
            ("CODE", n(l::DIAG_CODE)),
            ("MESSAGE_OFFSET", n(l::DIAG_MESSAGE_OFFSET)),
            ("MESSAGE_LENGTH", n(l::DIAG_MESSAGE_LENGTH)),
        ],
    )?;
    let kinds: Vec<(String, String)> = SegKind::ALL
        .iter()
        .map(|k| (format!("{k:?}"), (*k as u8).to_string()))
        .collect();
    let kinds: Vec<(&str, String)> = kinds.iter().map(|(a, b)| (a.as_str(), b.clone())).collect();
    object(s, "SEG_KIND", "Segment kinds (`SegKind`), by name.", &kinds)?;
    let flags: Vec<(&str, String)> = SegFlags::NAMED
        .iter()
        .map(|(name, f)| (*name, f.0.to_string()))
        .collect();
    object(
        s,
        "SEG_FLAG",
        "Segment flag bits (`SegFlags`, low byte).",
        &flags,
    )?;
    let sev: Vec<(String, String)> = Severity::ALL
        .iter()
        .map(|v| (format!("{v:?}"), v.id().to_string()))
        .collect();
    let sev: Vec<(&str, String)> = sev.iter().map(|(a, b)| (a.as_str(), b.clone())).collect();
    object(s, "SEVERITY", "Diagnostic severities, by name.", &sev)?;
    let codes: Vec<(String, String)> = DiagCode::ALL
        .iter()
        .map(|c| (format!("{c:?}"), c.id().to_string()))
        .collect();
    let codes: Vec<(&str, String)> = codes.iter().map(|(a, b)| (a.as_str(), b.clone())).collect();
    object(
        s,
        "DIAG_CODE",
        "Diagnostic codes (`DiagCode`), by name.",
        &codes,
    )?;
    // Drop the blank line after the last block.
    while s.ends_with("\n\n") {
        s.pop();
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn committed_path() -> std::path::PathBuf {
        std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .join(OUTPUT)
    }

    #[test]
    fn committed_file_is_up_to_date() {
        let committed = std::fs::read_to_string(committed_path()).unwrap_or_default();
        assert!(
            committed == generate(),
            "{OUTPUT} is out of date: run `cargo run -p gen-ts` and commit the result"
        );
    }

    #[test]
    fn output_names_every_kind_and_code() {
        let out = generate();
        assert!(out.contains("  ProgramEnd: 15,"));
        assert!(out.contains("  NotYetSimulated: 13,"));
        assert!(out.contains("export const MAGIC = 0x47435052;"));
        assert!(out.contains("  POSITION_UNKNOWN: 4,"));
    }
}
